{"implementation": "def solve(case):
    if 'nodes' not in case:
        raise ValueError("Missing 'nodes' field")
    if 'core_distance' not in case:
        raise ValueError("Missing 'core_distance' field")
    if 'distances' not in case:
        raise ValueError("Missing 'distances' field")

    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']
    n = len(nodes)

    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core distance for node {node}")

    mr_edges = []
    for edge in distances:
        u, v, dist = edge[0], edge[1], edge[2]
        cu = core_distance.get(u)
        cv = core_distance.get(v)
        if cu is None:
            raise ValueError(f"Node {u} in distances but not in core_distance")
        if cv is None:
            raise ValueError(f"Node {v} in distances but not in core_distance")
        # Canonicalize endpoints
        if u > v:
            u, v = v, u
        mr_weight = max(cu, cv, dist)
        mr_edges.append((mr_weight, u, v))

    # Sort by reachability weight, then by endpoint IDs for deterministic tie-breaking
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find structures (not mutating case)
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            nxt = parent[x]
            parent[x] = root
            x = nxt
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for weight, u, v in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == n - 1:
                break

    if n > 1 and len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
